from pathlib import Path
import json,sys
LOCAL='--local' in sys.argv
W=Path('/mnt/data/chunqiu_complete') if LOCAL else Path('_completion')
C=W/'input/current' if LOCAL else Path('.')
D={}
for p in (C/'sources/春秋左传/data').glob('zz-*.json'):
 d=json.loads(p.read_text());D[d['year_bce']]=d
OPS=[]
def refs(y,j=(),t=()):
 out=[]
 for k,kind,terms in [('j','jing',j),('t','zhuan',t)]:
  ps=next(x['text'] for x in D[y]['layers'] if x['kind']==kind).split('\n\n')
  for term in terms:
   if isinstance(term,int): ix=term
   else:
    hits=[i for i,p in enumerate(ps,1) if term in p]
    assert len(hits)==1,(y,k,term,hits);ix=hits[0]
   out.append([k,ix])
 return out
def add(y,h,d,j=(),t=(),note='',into=None,replace=False):
 OPS.append(dict(year=y,heading=h,detail=d,refs=refs(y,j,t),note=note,into=into,replace=replace))

add(710,'滕国国君来鲁朝见。','经文称来朝者为滕子；这与同年杞侯来朝、鲁军随后入杞不是一件事，分别保存。',j=['滕子来朝'])
add(707,'陈桓公去世后的葬礼也在本年举行。','经文另记“葬陈桓公”，不能只写春正月陈国内乱而省去葬事。',j=['葬陈桓公'],into=1)
add(707,'鲁国修筑祝丘。','经文把筑城列在本年后段，没有另记施工人数和工程规模，正文不补数字。',j=['城祝丘'])
add(706,'蔡人杀死陈佗。','这项记载紧接本年夏季纪事；它涉及陈国的君位冲突，不与去年陈桓公之死合成一事。',j=['蔡人杀陈佗'])
add(701,'秋七月，郑庄公安葬。','庄公之死及其后的郑国继承争端之外，经文还单独记下了七月的葬礼。',j=['葬郑庄公'],into=4)
add(697,'邾、牟、葛三国有人来鲁朝见。','经文分别称邾人、牟人、葛人，没有写出三位国君亲自来朝，故保留称谓范围。',j=['葛人来朝'])
add(685,'秋七月丁酉，齐国安葬齐襄公。','齐襄公死于前一年的内乱；公孙无知被杀、小白与子纠争位之后，本年才举行这次葬礼。',j=['葬齐襄公'])
add(684,'三月，宋国迁徙宿国。','经文作“宋人迁宿”，明确主导迁徙的是宋国；没有交代迁到哪里，不另补一个都城。',j=['宋人迁宿'])
add(666,'夏四月丁未，邾子琐去世。','这是邾国国君的死亡记录，与同年齐、卫及楚、郑战事分列。',j=['邾子琐卒'])
add(660,'冬，齐国高子来鲁结盟。','鲁国连续发生君位变乱以后，齐使高子来到鲁国。经文另记这次结盟，不能只写齐国支持复位便省去具体使者与盟事。',j=['齐高子来盟'])
add(656,'冬十二月，鲁公孙兹与齐、宋、卫、郑、许、曹诸军进攻陈国。','陈国求和以后，辕涛涂被放回。这次进军发生在召陵谈判及此前诸侯报复之后，不只是笼统的同一次“侵陈”。',j=['公孙兹帅师'],t=['叔孙戴伯'],into=4,note='传称叔孙戴伯，经称公孙兹，按同一人处理，不另立一位鲁军主将。')

add(706,'齐国再次向郑太子忽提婚事，他仍未接受。','早在鲁桓公与齐国婚姻以前，齐侯就曾想把文姜嫁给忽；忽以齐大非偶推辞。本年救齐以后，齐侯又向他提婚，忽不愿被看成借救援索取婚姻，于是再次拒绝。',t=['又请妻之'],into=6,replace=True,note='前一次明确写文姜，后一次只写“又请妻之”，没有再标女名。文姜此前已经嫁鲁，不能把两次都写成要将文姜嫁忽。')
add(674,'夏，郑厉公把周惠王接到郑国，安置在栎。','郑国调停未成，便使周王随自己回去。到秋季，周王与郑伯又进入邬和成周取宝器，暂时仍不是已经恢复王城统治。',t=['王处于栎'],into=3,replace=True,note='“遂以王归”是郑伯带王归郑；栎是此处的安置地。旧文“返回王畿，把他安置在栎”把方向写反，现依原段更正。')
add(632,'春，鲁国杀死驻卫的公子买，并向楚人解释。','公子买率兵戍卫，楚方一度准备救卫，后来未能成行。鲁僖公害怕晋国，杀公子买以求解脱，向楚人说他未能完成戍守任务。鲁军当时是否听命于不同强国的处境，与实际告知对象分开交代。',t=['谓楚人曰'],into=2,replace=True,note='原文“公惧于晋，杀子丛以说焉。谓楚人曰：不卒戍也。”明确受解释的是楚人；旧文写向晋国解释，现改正。子丛即公子买。')
add(625,'二月丁丑，鲁国迟至此时才制作僖公神主。','僖公此前已经下葬，作主却拖到这一年，因而受到“不时”的批评。这里不是说鲁国把仪式办得过早。',j=['作僖公主'],t=['作僖公主'],into=2,replace=True,note='《左传》仅作“不时”；《穀梁传》明确作“讥其后也”，杜预注解释为“过葬十月”。旧正文“过早”反其义，现更正。见[《日讲春秋解义》所汇三传原文](https://www.shidianguji.com/book/SK0457/chapter/1lxjgb9smyal7)。不将《公羊》与《左传》关于虞主、练主的异说强拼成同一种礼制。')
add(621,'春，晋国重新编军，赵盾先任中军佐，随后升到狐射姑之上并掌国政。','初次在夷地整军，狐射姑为中军将，赵盾佐之。阳处父自温回来后，改在董地检阅并交换中军班次，使赵盾居上。赵盾于是主持制定常法，整顿刑狱、逃亡、契约和官职，再交有关官员推行。',t=[1],into=2,replace=True,note='不能省去“改蒐于董，易中军”“是以上之”而一直把执政赵盾写作中军佐。阳处父支持赵氏及认为赵盾可任，是传文交代的理由，不当成编者的能力排名。')
add(618,'楚穆王听取范山建议，出兵伐郑。','范山指出晋君年幼，楚国可以向北行动。楚军驻于狼渊，俘虏郑公子坚、公子尨及乐耳，郑国随后与楚讲和。',t=['范山言于楚子'],into=4,replace=True,note='此时是楚穆王，楚庄王尚未即位。旧页误称楚庄王；本条改用相符的君号，出兵判断归于范山的进言。')
add(614,'晋国借魏寿馀假意背晋的计划，将士会从秦国接回。','晋国卿大夫商议后，让魏寿馀假装带魏地投秦，实际把他的家属留在晋。秦康公答应出面，士会奉派渡河同魏地官员说话；魏寿馀事先给他暗示，士会过河后被晋人接回。秦国随后归还其家属。',t=['魏寿馀伪'],into=1,replace=True,note='原文此年只称秦伯；秦穆公已于前621年去世，不能在前614年继续出场。绕朝赠策的旧段一并保留在引文，不凭赠策形制增加细节。')
add(598,'秋，晋国与各部狄人在欑函会合。','郤缺先向各部寻求和好；他们不满赤狄的役使，转而归附晋国。大夫原想把狄人叫来，郤缺主张晋方亲自前往，表示求人的一方不能不付出劳力。',t=[4,5],into=4,replace=True,note='原文没有“晋成公亲自会狄”的话。成公已在前600年去世，旧页所用君号错误；此次直接按郤缺及会合的记载叙述。')

add(710,'曲沃争位有更早的家族背景。','晋穆侯给长子取名仇，给次子取名成师；成师后来被封在曲沃，号桓叔，由栾宾辅佐。潘父曾杀晋昭侯、迎桓叔而未成，晋人另立孝侯；以后曲沃与翼地的争斗继续扩大。',t=['晋穆侯之夫人','惠之二十四年','惠之三十年'],into=7,note='这些都是以“初”及鲁惠公年数引入的往事，不归为前710年才出生、受封或被弑。保留回叙，不按本年一口气制造多次继位。')
add(675,'鬻拳也在楚文王的丧事之后自杀。','在这以前，他曾持兵器强谏楚王，认为自己以武力使君主屈从有罪，遂自断足，后来担任守门之职。楚王本年败归时，他曾不纳；王死以后，鬻拳安葬楚王，也自杀而被葬在绖皇。',t=[1,2,3],into=1,note='断足是此前经历，安葬楚王和自杀则接在本年丧事后。礼制评论不改写成编者赞许自伤或自杀。')
add(660,'春，虢军在渭汭击败犬戎，舟之侨随后离虢赴晋。','舟之侨不把这次胜利看成可以放心的理由，担心虢国仍有后患，遂奔晋。战胜与大夫离国是本段前后的两项行动。',t=[1])
add(660,'卫国复建以后，卫文公任内继续整顿民生和军政。','传文接写文公穿用粗朴衣冠，注意农事、工商业和教导任用；即位之初兵车三十乘，到其在位末年增为三百乘。它补充卫国从败亡中恢复的过程，但不把整个任期的发展全记在这一年。',t=['卫文公大布之衣'],into=8,note='“元年”“季年”显然跨越任期，三十乘和三百乘不是前660年内先后统计的两个数字。成风托付季友僖公的前事也见T011，不另造本年新托孤。')
add(658,'齐国寺人貂在多鱼泄漏军情。','原段很短，只记这一次泄密及地名，没有交代秘密泄给了谁，也没有列出一场由此造成的败战。',t=['漏师'],note='“漏师”依杜预注作泄漏军事密谋，不是军队在多鱼走失。参见[《古今图书集成》所引《左传》及杜注](https://zh.wikisource.org/zh-hans/欽定古今圖書集成/明倫彙編/宮闈典/第126卷#寺人貂)。')
add(658,'虢公在桑田击败戎人。','晋国卜偃听说后，担心虢国在丢失下阳以后反因另一场胜利而轻忽晋军。这里只把战胜记为本年史事，不把卜偃所说的亡国期限当成本年已发生。',t=['虢公败戎于桑田'])
add(655,'陈辕涛涂先帮助郑申侯修邑，随后又告发他图谋背郑。','辕涛涂记恨申侯在召陵使自己获罪，便劝申侯把所得邑城修得漂亮，代为向诸侯请求。工程完成后，他转向郑伯告发，说申侯如此修城是准备叛变，申侯因此获罪。',t=['陈辕宣仲'],note='辕宣仲即本条辕涛涂；这是前653年申侯被杀之前的一段陷害过程，不提前写成已经处死。')
add(651,'齐桓公还率诸侯军到高梁，讨问晋国内乱。','这支军队抵达高梁以后便返回。鲁国没有接到这次行动的命令，因此经文未专列鲁国参加伐晋；不能仅用秦、齐协助夷吾来概括所有干预。',t=['齐侯以诸侯之师伐晋'],into=6)
add(648,'春，诸侯为卫国楚丘修筑外城。','卫国已迁定楚丘，但仍担心狄人再次进攻；本次是加筑外郭，不是前658年安置卫国的同一次初建。',t=['诸侯城卫楚丘之郛'])
add(647,'春，齐国仲孙湫聘周，准备为王子带求情，却未开口。','办完正式使事以后，仲孙湫没有谈王子带，回齐说周王怒气未消。他提出的多年后才可能召回只是判断，不当成本年王子带已经归国。',t=[1])
add(645,'晋惠公被俘期间，晋国以赏田、整备军赋安定国人。','吕甥让人借君命向国人传达，晋君虽能回来，也已使社稷受辱，可以考虑辅立太子圉。国人表示愿意继续支持，晋国遂作爰田，又整备兵赋、作州兵，使人们看到即使国君暂不能返，也仍有继承与抵抗的安排。',t=['晋于是乎作爰田'],note='爰田、州兵依本段原名保留；本轮不把它直接称为一次已经考定的私有土地革命或全民征兵制度。')
add(643,'夏，晋太子圉到秦国为质，秦国归还晋河东并把女子嫁给他。','原文随后回叙夷吾在梁时娶梁女，生圉及其妹；圉此次赴秦，其妹也作为宦女同行。婚姻、归地和质子共同属于秦晋在韩原之战后的安排。',t=['晋大子圉为质于秦'],note='梁伯嫁女及怀孕占卜是太子出生前事，不误编成本年。秦方嫁给圉的女子与他后来离秦时的嬴氏在后续相接。')
add(638,'晋太子圉逃离秦国，妻子嬴氏没有同行。','圉准备回晋，问嬴氏是否一起走。她认为圉身为晋太子想返国可以理解，自己却奉秦君之命侍奉，不能擅弃使命，所以既不跟走，也不告发。圉遂独自逃归。',t=['晋大子圉为质于秦'])
add(638,'周襄王听从富辰劝告，将王子带从齐国召回京师。','富辰以兄弟不和便难以要求诸侯相睦为由进言，王同意召回。王子带以后再次卷入争位是后来之事，不能用后果倒写成本年召回时已经爆发内战。',t=['王子带自齐复归'])
add(636,'卫国准备攻邢，礼至兄弟先到邢国任职。','礼至认为若不能接近邢国守城的人，便难以取其国，于是请求同兄弟前往邢国求仕。兄弟得到任职，为下一年卫军进攻作内应。',t=['礼至曰'],note='这是前635年灭邢的前期安排，不将邢国灭亡提前一年。')
add(632,'六月，卫侯郑从楚国回到卫国。','归国日期及出发地在经文明确可见；与卫国拒战、立叔武及后续受拘等事分开，不省去“自楚复归”的环节。',j=['卫侯郑自楚'],into=9)
add(630,'东门襄仲本拟出聘周王室，随后首次出聘晋国。','鲁国与晋的聘问关系由此又添一项具体使事。原文说的是襄仲的行动，不与本年周使来鲁混成一趟出行。',t=['东门襄仲'])
add(627,'箕之战以后，晋襄公升赏先且居、胥臣与郤缺。','先且居被命为中军将，胥臣因早先推荐郤缺而受赏，郤缺也升为卿并收回冀地。早年胥臣途经冀，看到郤缺耕田、妻子送饭而相敬，便向晋文公推荐；文公虽顾虑其父有罪，仍任用他。',t=['臼季使过冀'],into=10,note='臼季即本条推荐者胥臣。妻子送饭、晋文公首次任用是此前经历；本年实际记事是晋襄公在箕战后的命赏。')
add(626,'鲁国本年将闰月置在三月，传文批评这种安排。','作者从一年开始、中间校正和岁末归余的原则解释“不合礼”的理由。记录保留古历原文，不自行计算成公历中的闰三月。',t=['于是闰三月'],note='这是历制说明，不用现代公历闰年规则代替原书所论。')
add(625,'狼瞫在彭衙率自己所属冲击秦军，战死阵中。','他原在殽战后被选为晋君车右，到箕之役又被先轸黜换，曾拒绝朋友鼓动作乱的建议。本次两军列阵后，他带人冲入秦军，晋军随之进攻而获胜。',t=['狼瞫取戈'],into=1,note='殽、箕两战只是交代被选、被黜的前事；不得将狼瞫先前杀俘、担任车右也记成前625年的新任命。')
add(624,'卫君前往陈国，感谢陈国促成自己与晋国和解。','“拜晋成”是为晋卫讲和而致谢，不写成卫国此时又与陈国订立一项未经记载的新盟。',t=['卫侯如陈'])
add(623,'春，晋国释放孔达，让他回卫。','晋方认为孔达是卫国所需的人，因而免去其罪而归之。这与同年甯武子来鲁聘问不是同一使事。',t=['晋人归孔达'])
add(620,'荀林父早先曾劝先蔑不要参与从国外另迎晋君，先蔑没有接受。','他指出夫人和太子都还在，外迎国君的计划很难实行。先蔑后来出奔秦国，荀林父仍把他的家属、器用和财物送去，说这是为旧同僚尽心。',t=['先蔑之使也'],into=4,note='劝阻发生在出使迎君以前；送家属财物则接在本次流亡后，不把前一年迎君再记成前620年新出使。')
add(618,'春正月，晋国先克被刺杀，随后才有对作乱诸臣的处置。','晋国相继杀先都、梁益耳等人的经过，须与先克先被杀的起因连读，不能只留下处死名单。',t=[1],into=3)
add(618,'夏秋之间，陈国与楚军先后交战，最终才求和。','夏季楚军侵陈、攻取壶丘，报复陈国依晋；秋季楚公子朱从东夷方向攻陈，却被陈军击败，公子茷被俘。陈人担心楚国继续报复，随后与楚讲和。',t=[6,7],into=6,note='原段不仅记“陈服楚”，还记陈军曾取胜，不可把整个过程写成两次陈国战败。')
add(615,'楚令尹大孙伯去世，成嘉继任。','传文把令尹更替与群舒叛楚连续记载，本年之后的征舒、围巢由新局势展开。',t=['楚令尹大孙伯卒'])
add(614,'春，晋国派詹嘉驻守瑕，守备桃林之塞。','这是一项边塞驻防任命，与夏季诱回士会的行动分开保存。',t=['使詹嘉处瑕'])
add(613,'周王室争政案诉至晋国，赵盾调处以后将有关人员送回。','周公阅与王孙苏本要到晋国争讼，周王转而疏远王孙苏，让尹氏、聃启同周公在晋国对诉。赵盾居中平定王室争端，使其复归。',t=['周公将与王孙苏讼'],note='“复之”的具体复归对象在本段不宜无限扩大；本条保留调处，不另造王室全部官职名单。')
add(611,'传文另记有蛇从泉宫出来、进入国都。','原文将蛇的数目比作鲁国先君之数。这是本年所录的异象说法，不把它当成能够预测君主死亡的现代证据。',t=['有蛇自泉宫出'],note='本条保留传文内容层，既不据其证明神意，也不补造蛇的品种和实际调查记录。')
add(610,'晋国也把赵穿、公婿池送到郑国为质。','晋遣巩朔与郑讲和时，先安排两人留郑；冬十月郑太子夷、石楚再到晋国。双方交换人质，不能只写郑国一方。',t=['赵穿、公婿池为质','郑大子夷、石楚'],into=6)
add(606,'晋军先伐郑至郔，士会入郑主持盟誓。','郑国在这次行动后与晋讲和，后来又遭楚军进攻，才更能看清郑在两大国之间来回承压的过程。',t=['晋侯伐郑，及郔'])
add(605,'郑公子去疾先辞君位，又阻止襄公清除穆氏诸公子。','国人最初推去疾即位，他以公子坚年长为由辞让。坚成为襄公后，想排除穆公其他后人而独留去疾；去疾表示诸兄弟应同存亡，襄公于是保留他们，使为大夫。',t=['郑人立子良'],into=4,note='子良即去疾，与公子坚不是一人；“以顺”在这里关系到兄弟长幼，不擅改成某种现代选举。')
add(601,'晋国以郤缺执政，秋季免去胥克，命赵朔佐下军。','原文先记胥克有疾、郤缺执政，秋季再记免职和赵朔的新军职。疾病只按古书用语记录，不作诊断。',t=[5,6],note='若原文以“蛊”记病，也只视为古籍用语，不由此说明病原或精神状态。')
add(598,'楚左尹子重还率军侵宋，楚王在郔等待。','同段随后写蒍艾猎营建沂城：先估算事务、期限、财用与工具，安排粮食和劳役，三旬告成。军事与营建都在该段，不只保留筑城。',t=[3],into=3)
add(597,'邲之战期间，郑国石制曾引楚军入郑，图谋分郑并另立公子鱼臣。','郑国后来杀仆叔、子服，传文把它放在借乱谋利的讨论中。这里只记实际引军、谋立和诛杀，不将图谋写成已经分出一个新郑国。',t=['郑石制'])
add(597,'郑伯、许男到楚国朝见。','两国向楚表示归附，是本年战后外交中的一项具体行动。',t=['郑伯、许男如楚'])
add(597,'楚围萧以前曾答应：萧若不杀所获楚人，楚军可以退去。','萧人仍杀了熊相宜僚、公子丙，楚军随后围城。军中天寒，巫臣提醒楚王体恤士卒，楚王巡军慰劳。传文还写还无社与申叔展约定，以枯井上的茅绖为藏身信号；萧溃以后，申叔展循信号救他出来。',t=['冬，楚子伐萧'],into=9,note='麦麹、山鞠穷、河鱼腹疾和眢井的问答属于隐语式情节，本条只说明求救约定，不提供现代医疗解释。萧溃在同段复述，不重复算两次灭萧。')
add(594,'晋侯将狄臣千室赏给荀林父，又赏士伯瓜衍之县。','士伯此前曾为荀林父进言，晋侯认为自己能获狄土也与留下荀林父有关，故同时赏赐。随后赵同奉命向周王献狄俘，刘康公对其失礼提出批评。',t=['狄臣千室','使赵同献狄俘'],into=5,note='“千室”照录为来源数字；刘康公关于赵同将有大咎的预言不另算成本年已经遭祸。')
add(589,'楚使屈巫携夏姬离楚，最后到晋国任邢大夫。','屈巫即申公巫臣。楚国前此讨陈、邲之战中夏姬丈夫襄老战死以后，巫臣安排夏姬先回郑，自己向郑聘娶。本年奉命聘齐、通告楚军行动时，他带全家出行，到了郑国让副使带聘币回楚，自己携夏姬北走；听闻齐新败，转而经郤至投晋。',t=[16,17,18,19],note='前598年楚讨陈、前597年邲战以及早先归郑是本次出亡的前事。巫臣所说夏姬使多名男子、国家受祸是人物言辞，不采用这种归咎女性的评价作编者判断。')
add(589,'楚军侵鲁时，鲁国送出工匠并让公衡为质，求得讲和。','臧孙起先不肯前往赂楚，认为楚军路远、久留自会撤退。楚军进到阳桥后，孟孙请往，送执斫、执针、织纴各百人，并以公衡为质。后来楚军到宋，公衡逃回，臧宣叔担心此举危及鲁国与楚的约定。',t=['冬，楚师侵卫','公衡逃归'],into=8,note='工匠人数为原载，不当作现代核定人口数。公衡逃归与在蜀议盟相接，不写成楚国当即因他再攻鲁。')
add(589,'晋巩朔向周王报献鞌之战胜利，周王不肯按献捷之礼接见。','周王让单襄公说明：齐是姻亲之国，即使有王命讨伐，战后也应告事而不炫功；何况来使等级不合既有安排。王室最后由三吏接待，按大夫告庆之礼办理，又私下宴赐巩朔，并要求不列作正式礼制。',t=['巩朔献齐捷'],note='不接见献捷不等于完全拒绝来使；正式礼与私下宴赐分别保存。')
add(581,'春，晋国使籴茷出聘楚国，回报楚大宰子商的聘问。','到了秋季鲁君被留晋送葬时，籴茷仍未归来；出使及后文相接，不误作另一人。',t=['使籴茷如楚'])
add(578,'参加联军的王室大臣成肃公在瑕去世。','他与刘康公等参加本次诸侯行动，死亡是传文独有的短条，不因不是鲁国卿大夫就略去。',t=['成肃公卒于瑕'])
add(577,'卫君病中先命孔成子、甯惠子立衎为太子。','衎的母亲为敬姒。先立太子再发生国君丧事，继承安排的先后在原文中可见。',t=['敬姒之子衎'],into=5)
add(575,'晋将郤至奉命到周王室告捷，与单襄公谈话。','郤至把胜利多归于自己，单襄公则向周臣说明，军政之功不能由一人独占。他还批评郤至拿三卿作比较、借称别人无能来为自己邀功。',t=['郤至献楚捷'],note='保留双方谈话，不把单襄公对其后患的推断写成已经发生；更不将对三卿的比较转为编者的人物优劣排名。')
add(574,'郑国派太子髡顽、侯獳到楚为质，楚公子成、公子寅驻守郑国。','随后鲁君会同王室代表和诸侯军伐郑，进至曲洧一线。质子与驻军是郑楚关系的具体安排，补入这场战争的背景。',t=['侯獳为质于楚'],into=1)
add(574,'六月戊辰，晋国士燮去世。','他从鄢陵之战回来后，曾向家中祝宗表达自己不愿见到胜战后的内乱；本年死亡有干支，不能只把他作为去年战场中的劝谏者写过便略去。',t=['六月戊辰，士燮卒'],note='向祝宗祈死是古书记录的言辞，不写成祈祷已被证明导致死亡，也不据此诊断人物状态。')

add(651,'十一月，卓子也被里克杀死，荀息随之而死。','奚齐死后，荀息原想殉死，经人劝说先立卓子、主持献公葬礼。里克接着在朝廷杀卓子，荀息终于兑现了与献公所作的承诺。',t=[6,7],into=5,note='《左传》在僖公九年十一月记卓子、荀息之死，《春秋》经却将相应条目列在十年。正文按传文明确的事件月次接写；前650年保留经文的记年差别，不再讲成又死一次。')
add(650,'晋惠公立定以后，四月杀里克。','周公忌父、王子党会齐隰朋拥立晋侯。惠公随后以里克曾杀二君一大夫为由命其死，里克伏剑自杀。丕郑当时在秦国聘问、解释晋方迟交赂物，所以未同时被杀。',t=[2],j=['晋里克弑其君'],into=3,replace=True,note='经文在本年列“晋里克弑其君卓及其大夫荀息”，传文则明确列在前一年十一月。本页保留经传年差，卓、荀息的实际经过统一见前651年，不据经传分年造出两次死亡。')
add(575,'鄢陵开战前，晋军内部仍在争论是否应战。','范文子主张避战，栾书主张固守等待；郤至指出楚军阵列与内部配合的弱点，要求抓住战机。楚王在巢车上观察晋军，由伯州犁说明对方动作；晋侯一侧的苗贲皇则建议先打楚左右两翼，再集兵攻王卒。晋方车驾一度陷泥，栾鍼拒绝让中军将越职代驾，仍按本职救出晋侯。',t=[4,5,6,7,8],into=5,note='两边人物所说天意、占卜与预测是战前言论，不能当作战争结果的独立证明；叙述不替任何主将作能力排序。')
add(575,'晋吕锜射伤楚共王的眼睛，养由基奉命射死吕锜。','交战中郤至遇到楚王仍依礼避让，楚方遣工尹襄致问，他按军中礼答谢。韩厥、郤至先后追近郑君又停手，郑君收起旗帜脱离追击，唐苟留下战死。楚军退至险处时，养由基与叔山冉反击，晋军停止逼近并俘获楚公子茷；栾鍼又在战间向子重送饮，复鼓后继续作战。',t=[9,10,11,12,13],into=5,note='吕锜的梦、占辞及穿七札等夸饰性描述完整留在史料段，不扩写成现代实验所得的武器性能。双方在战间行礼，不表示战争本身没有杀伤。')
add(575,'战斗从清晨延续到见星，楚军原准备补卒乘、整车马再战。','晋军也发出整备再战的命令，并放回楚俘，使消息传到楚王。楚王召子反商议时，子反因穀阳竖献酒而醉，不能入见，楚军于是夜退。晋军进入楚营取食三日，范文子仍劝晋君不要因获胜失去戒心。',t=[14],into=5,note='“天败楚”的话属于楚王的表达。子反退军后的死另见第6条，不把他的死亡放在夜间撤军之前。')
TEXT_FIXES={
'years/bce-0700-0601/bce-0660.md':[['齐国后来把她抓回，在夷地杀死。','齐国后来将她带回，并在夷地杀死。']],
'years/bce-0700-0601/bce-0645.md':[['9. **冬，宋国攻曹；楚军在娄林击败徐军。** 中原与南方战线同时持续。[9]','9. **冬，宋国进攻曹国，报复旧怨。** 楚军在娄林与徐交战的同一件事见本页第4条，不重复列为第二次楚徐战争。[9]']],
'years/bce-0700-0601/bce-0611.md':[['鲁国君主健康明显恶化。','原文只交代四次不视朔及有疾，不据此推断具体病情。']],
'years/bce-0700-0601/bce-0616.md':[['到这一时期鄋瞒势力基本消失。','传文接着总述鄋瞒势力最终消失。'],['7. **长狄部族过去也曾攻宋、齐、卫、晋，多个“长狄”首领先后被各国捕杀；','7. **传文回叙并预叙长狄与宋、齐、卫、晋的交战，多名首领先后被捕杀；']],
'years/bce-0700-0601/bce-0608.md':[['晋国继续整顿邲战前的军政体系。','这是追究此前河曲之役中违命的军将，不把尚未发生的邲战写成此次处置原因。']],
'years/bce-0700-0601/bce-0609.md':[['12. **宋国武氏宗族也在这一年图谋内乱，宋文公随后诛杀同母弟须及昭公诸子，驱逐武、穆之族。** 宋国内部继续清洗公族。[12]','12. **宋国武氏宗族的内乱在传文中接叙到这一年。** 宋文公诛须及昭公诸子、逐武穆之族的详细纪年另见前606年；这里保留传文间的年次差别，不认作两次相同清洗。[12]']]
}
(W/'outside_patches.json').write_text(json.dumps({'ops':OPS,'text_fixes':TEXT_FIXES},ensure_ascii=False,indent=2))
print('operations',len(OPS),'years',len(set(o['year'] for o in OPS)),'new events',sum(o['into'] is None for o in OPS),'replacement',sum(o['replace'] for o in OPS))
